// The bench's policy (e2e/scenarios/base-overlays): the job image has neither conftest nor opa, so this
// is plywood.yml's policy.command, printing conftest's JSON shape over the change set.
import { readFileSync } from "node:fs";
const input = JSON.parse(readFileSync(process.argv[2], "utf8"));
const { name } = JSON.parse(readFileSync(new URL("./denied.json", import.meta.url), "utf8"));
const failures = (input.changeSet?.entries ?? [])
  .filter((e) => ["update", "replace"].includes(e.action) && e.address.endsWith(`::${name}`))
  .map((e) => ({ msg: `${e.address} is frozen by the bench's policy`, metadata: { query: "data.main.deny_frozen" } }));
console.log(JSON.stringify([{ filename: "change-set", namespace: "main", successes: 0, failures }]));
process.exit(failures.length ? 1 : 0);
